import { createWorkspace, teardownWorkspace } from "@tigrisdata/agent-kit";
import { PutObjectCommand, S3Client } from "@aws-sdk/client-s3";
import { writeFile } from "node:fs/promises";

type WorkspaceData = {
  bucket?: string;
  credentials?: {
    accessKeyId?: string;
    secretAccessKey?: string;
  };
};

type WorkspaceResponse = {
  error?: { message?: string };
  data?: WorkspaceData;
};

const ensureWorkspaceData = (
  response: WorkspaceResponse,
  name: string,
): { bucket: string; credentials: { accessKeyId: string; secretAccessKey: string } } => {
  if (response.error) {
    const message = response.error.message ?? "Unknown error";
    throw new Error(`Failed to create workspace ${name}: ${message}`);
  }

  if (!response.data) {
    throw new Error(`Workspace ${name} response missing data`);
  }

  const { bucket, credentials } = response.data;
  if (!bucket) {
    throw new Error(`Workspace ${name} response missing bucket`);
  }

  if (!credentials?.accessKeyId || !credentials.secretAccessKey) {
    throw new Error(`Workspace ${name} response missing credentials`);
  }

  return {
    bucket,
    credentials: {
      accessKeyId: credentials.accessKeyId,
      secretAccessKey: credentials.secretAccessKey,
    },
  };
};

const createSummary = (params: {
  writerBucket: string;
  readerBucket: string;
  writerPutOk: boolean;
  readonlyPutBlocked: boolean;
}) => ({
  writer_bucket: params.writerBucket,
  reader_bucket: params.readerBucket,
  writer_put_ok: params.writerPutOk,
  readonly_put_blocked: params.readonlyPutBlocked,
});

const isReadonlyBlockedError = (error: unknown): boolean => {
  if (!error || typeof error !== "object") {
    return false;
  }

  const maybeError = error as {
    name?: string;
    Code?: string;
    $metadata?: { httpStatusCode?: number };
  };

  const errorName = maybeError.name ?? maybeError.Code;
  if (errorName && ["AccessDenied", "NotImplemented"].includes(errorName)) {
    return true;
  }

  return maybeError.$metadata?.httpStatusCode === 403;
};

const main = async () => {
  const [writerResponse, readerResponse] = await Promise.all([
    createWorkspace("writer-ws", { credentials: { role: "Editor" } }),
    createWorkspace("reader-ws", { credentials: { role: "ReadOnly" } }),
  ]);

  const writerWorkspace = ensureWorkspaceData(writerResponse as WorkspaceResponse, "writer-ws");
  const readerWorkspace = ensureWorkspaceData(readerResponse as WorkspaceResponse, "reader-ws");

  const writerClient = new S3Client({
    region: "REDACTED",
    endpoint: "REDACTED",
    credentials: {
      accessKeyId: writerWorkspace.credentials.accessKeyId,
      secretAccessKey: writerWorkspace.credentials.secretAccessKey,
    },
  });

  const readerClient = new S3Client({
    region: "REDACTED",
    endpoint: "REDACTED",
    credentials: {
      accessKeyId: readerWorkspace.credentials.accessKeyId,
      secretAccessKey: readerWorkspace.credentials.secretAccessKey,
    },
  });

  let writerPutOk = false;
  let readonlyPutBlocked = false;

  try {
    await writerClient.send(
      new PutObjectCommand({
        Bucket: writerWorkspace.bucket,
        Key: "note.txt",
        Body: "hello dual role",
      }),
    );
    writerPutOk = true;

    try {
      await readerClient.send(
        new PutObjectCommand({
          Bucket: readerWorkspace.bucket,
          Key: "note.txt",
          Body: "should be blocked",
        }),
      );
      readonlyPutBlocked = false;
    } catch (error) {
      readonlyPutBlocked = isReadonlyBlockedError(error);
    }

    const summary = createSummary({
      writerBucket: "writer-ws",
      readerBucket: "reader-ws",
      writerPutOk,
      readonlyPutBlocked,
    });

    await writeFile(
      "/home/user/dual-role/result.json",
      `${JSON.stringify(summary, null, 2)}\n`,
    );
  } finally {
    await Promise.all([
      teardownWorkspace("writer-ws"),
      teardownWorkspace("reader-ws"),
    ]);
  }
};

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
